// Regenerate Settings defaults from the two shipped keymaps.
// Runs of bindings both keymaps share are emitted once, so the generated file itself
// keeps the no-repeated-code rule the CI check holds every source file to.
import { readFile, writeFile } from "node:fs/promises";
import { shippedKeymap } from "../kanso/mods/kanso-panel/platform-keymap.js";

const root = new URL("../", import.meta.url);
const files = [...new Set(["macos", "windows"].map(shippedKeymap))];
const maps = Object.fromEntries(await Promise.all(files.map(async (file) => [file, JSON.parse(await readFile(new URL(file, root), "utf8"))])));

const q = (text) => JSON.stringify(text);
const indent = (n) => " ".repeat(n);

// Maximal runs (two or more) of consecutive entries the other section shares, key and action
// alike, and holds in the same order, so one const can stand in for both.
function sharedRuns(entries, otherEntries) {
  const at = new Map(otherEntries.map(([key, value], index) => [key, { value, index }]));
  const marks = entries.map(([key, value]) => {
    const found = at.get(key);
    return found && found.value === value ? found.index : null;
  });
  return marks.reduce((runs, atOther, i) => {
    if (atOther === null) return runs;
    const prev = runs.at(-1);
    return prev && prev.end === i && prev.atEnd + 1 === atOther
      ? [...runs.slice(0, -1), { ...prev, end: i + 1, atEnd: atOther }]
      : [...runs, { start: i, end: i + 1, atStart: atOther, atEnd: atOther }];
  }, []).filter((run) => run.end - run.start >= 2);
}

// Each file's sections as pieces: literal entries, and the shared runs by their entries.
const plans = files.map((file, f) => {
  const other = maps[files[1 - f]];
  return Object.entries(maps[file]).map(([section, obj]) => {
    const entries = Object.entries(obj);
    const otherSection = other?.[section];
    const runs = otherSection ? sharedRuns(entries, Object.entries(otherSection)) : [];
    const pieces = runs.flatMap((run, r) => [
      { kind: "literal", entries: entries.slice(runs[r - 1]?.end ?? 0, run.start) },
      { kind: "shared", slice: entries.slice(run.start, run.end) },
    ]).concat([{ kind: "literal", entries: entries.slice(runs.at(-1)?.end ?? 0) }]);
    return [section, pieces.filter((piece) => piece.kind === "shared" || piece.entries.length)];
  });
});

// One name per distinct shared run, in the order the first keymap meets them.
const sharedIds = [...new Set(plans.flat().flatMap(([, pieces]) => pieces.filter((piece) => piece.kind === "shared").map((piece) => q(piece.slice))))];
const nameOf = new Map(sharedIds.map((id, i) => [id, `onBoth${i + 1}`]));

const constLines = sharedIds.flatMap((id) => [
  `const ${nameOf.get(id)} = {`,
  ...JSON.parse(id).map(([key, value]) => `${indent(2)}${q(key)}: ${q(value)},`),
  "};",
]);

const fileLines = plans.flatMap((sections, f) => [
  `${indent(2)}${q(files[f])}: {`,
  ...sections.flatMap(([section, pieces]) => [
    `${indent(4)}${q(section)}: {`,
    ...pieces.flatMap((piece) => piece.kind === "shared"
      ? [`${indent(6)}...${nameOf.get(q(piece.slice))},`]
      : piece.entries.map(([key, value]) => `${indent(6)}${q(key)}: ${q(value)},`)),
    `${indent(4)}},`,
  ]),
  `${indent(2)}},`,
]);

const text = ["// Generated by scripts/sync-keys.mjs.", ...constLines, "", "export const DEFAULT_KEYS = {", ...fileLines, "};"].join("\n");
await writeFile(new URL("kanso/mods/kanso-settings/defaults.js", root), `${text}\n`);
